import{_ as a,k as o,C as r,a6 as s,A as i,j as n}from"./chunks/framework.BZrHWrhq.js";const l="/bwe/assets/images/general/getting-started/menu-page.png",d="/bwe/assets/images/general/getting-started/world-settings.png",c="/bwe/assets/images/general/getting-started/view-database.png",p="/bwe/assets/images/general/getting-started/integrations.png",w=JSON.parse('{"title":"Getting Started","description":"What to do after you install the application.","frontmatter":{"title":"Getting Started","page_title":"Getting Started","description":"What to do after you install the application.","nav_order":4,"mentions":["Aevarkan"]},"headers":[{"level":2,"title":"World View","slug":"world-view","link":"#world-view","children":[]},{"level":2,"title":"Database Tab","slug":"database-tab","link":"#database-tab","children":[]},{"level":2,"title":"Integrations Tab","slug":"integrations-tab","link":"#integrations-tab","children":[]}],"relativePath":"general/getting-started.md","filePath":"general/getting-started.md"}'),g={name:"general/getting-started.md"};function h(b,e,u,m,f,k){const t=i("template-WorkInProgress");return n(),o("div",null,[r(t),e[0]||(e[0]=s('<p>Upon opening the app, you will be greeted by a list of your Minecraft worlds. If your world doesn&#39;t appear, try pressing &quot;Show more&quot; at the bottom of the list.</p><p>To begin editing, open the world you&#39;ll be making changes to by clicking on its tab in the list.</p><p><img src="'+l+'" alt="World directory"></p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>If your world still doesn&#39;t show up after pressing &quot;Show more&quot;, then that is a bug. File an issue <a href="https://github.com/8Crafter-Studios/Bedrock-World-Editor/issues" target="_blank" rel="noreferrer">here</a> with details of your Minecraft configuration.</p></div><h2 id="world-view" tabindex="-1">World View <a class="header-anchor" href="#world-view" aria-label="Permalink to &quot;World View&quot;">​</a></h2><p>Once you have opened a world, you will see a selection of tabs to the left, each pertaining to an aspect of the world you can edit. Here, the <code class="shiki"><span>World Settings</span></code> tab is selected.</p><p>Depending on the tab, you may have a selection of <code class="shiki"><span>Node</span></code>, <code class="shiki"><span>Prismarine-NBT</span></code>, <code class="shiki"><span>SNBT</span></code>, or another format of displaying the data. For most tabs, the <code class="shiki"><span>Node</span></code> editor format will be available.</p><p><img src="'+d+'" alt="World settings tab"></p><h2 id="database-tab" tabindex="-1">Database Tab <a class="header-anchor" href="#database-tab" aria-label="Permalink to &quot;Database Tab&quot;">​</a></h2><p>Minecraft Bedrock uses <a href="https://minecraft.wiki/w/Bedrock_Edition_level_format" target="_blank" rel="noreferrer">LevelDB</a> to store world data, a flat key-value database. Due to this flat nature, every single key-value pair can be sorted in one list. This is what the <code class="shiki"><span>View Files</span></code> tab displays.</p><p><img src="'+c+'" alt="Database view"></p><h2 id="integrations-tab" tabindex="-1">Integrations Tab <a class="header-anchor" href="#integrations-tab" aria-label="Permalink to &quot;Integrations Tab&quot;">​</a></h2><p>As the Script API for Minecraft Bedrock is rather limiting, add-ons can struggle to implement advanced features. The <code class="shiki"><span>Integrations</span></code> tab allows add-ons to leverage Bedrock World Editor&#39;s capabilities, bypassing constraints of the Script API.</p><p>Currently, <a href="https://mcpedl.com/worldedit-be-addon/" target="_blank" rel="noreferrer">WorldEdit Bedrock</a> by <a href="https://github.com/SIsilicon" target="_blank" rel="noreferrer">SIsilicon</a> leverages Bedrock World Editor for its biome modification and structure import export features. For more information, see the dedicated integration page <a href="./../integrations/worldedit-bedrock">here</a>.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Integrations are implemented on a case-by-case basis. If you would like to add an integration for your add-on, make a suggestion <a href="https://github.com/8Crafter-Studios/Bedrock-World-Editor/issues/new?template=integration-suggestion.md" target="_blank" rel="noreferrer">here</a>.</p></div><p><img src="'+p+'" alt="Integrations tab"></p>',16))])}const v=a(g,[["render",h]]);export{w as __pageData,v as default};
